package app.yougram.feature.assistant.data

/** Все булевы настройки, которыми может управлять ассистент (сгенерировано из SettingsRepository). */
internal object AiToggles {
    private fun t(name: String, vararg keys: String, block: (app.yougram.core.settings.SettingsRepository, Boolean) -> Unit) =
        AiSetting(name, listOf("вкл", "выкл"), keys.toList()) { s, v -> block(s, v == "вкл") }

    val all: List<AiSetting> = listOf(
        t("Уведомления из личных чатов", "личн+уведомл") { s, v -> s.updateNotifications { it.copy(privateChats = v) } },
        t("Уведомления из групп", "групп+уведомл") { s, v -> s.updateNotifications { it.copy(groups = v) } },
        t("Уведомления из каналов", "канал+уведомл") { s, v -> s.updateNotifications { it.copy(channels = v) } },
        t("Уведомления об историях", "истор+уведомл") { s, v -> s.updateNotifications { it.copy(stories = v) } },
        t("Уведомления о реакциях", "реакц") { s, v -> s.updateNotifications { it.copy(reactions = v) } },
        t("Счётчик на значке", "счетчик", "значок+счет") { s, v -> s.updateNotifications { it.copy(showCounter = v) } },
        t("Считать отключённые чаты", "считать+отключ", "счет+отключ", "счет+заглуш") { s, v -> s.updateNotifications { it.copy(countMuted = v) } },
        t("Считать сообщения, а не чаты", "считать+сообщен") { s, v -> s.updateNotifications { it.copy(countMessages = v) } },
        t("Текст сообщений в уведомлениях", "предпросмотр+уведомл", "текст+уведомл", "превью+уведомл") { s, v -> s.updateNotifications { it.copy(preview = v) } },
        t("Звук уведомлений", "звук+уведомл", "звук уведомл") { s, v -> s.updateNotifications { it.copy(sound = v) } },
        t("Вибрация уведомлений", "вибрац") { s, v -> s.updateNotifications { it.copy(vibration = v) } },
        t("Звуки в чате", "звук+чат") { s, v -> s.updateNotifications { it.copy(chatSound = v) } },
        t("Всплывающие уведомления", "всплыва") { s, v -> s.updateNotifications { it.copy(popups = v) } },
        t("Уведомлять, когда контакт в Telegram", "контакт+присоедин", "контакт+появ", "зарегистрирова") { s, v -> s.updateNotifications { it.copy(contactJoined = v) } },
        t("Уведомления о закреплённых сообщениях", "закреплен") { s, v -> s.updateNotifications { it.copy(pinnedMessages = v) } },
        t("Перезапуск при закрытии", "перезапуск") { s, v -> s.updateNotifications { it.copy(restartOnClose = v) } },
        t("Фоновое соединение", "фонов+соедин", "фоновое") { s, v -> s.updateNotifications { it.copy(backgroundConnection = v) } },
        t("Поиск в верхней панели", "поиск+верх", "поиск+панел") { s, v -> s.updateChatPrefs { it.copy(searchOnTop = v) } },
        t("Истории в списке чатов", "истории", "история") { s, v -> s.updateChatPrefs { it.copy(hideStories = !v) } },
        t("Автопрокрутка к новым сообщениям", "автопрокрут", "прокручив+нов") { s, v -> s.updateChatPrefs { it.copy(autoScrollNew = v) } },
        t("Автоночной режим", "автоночн", "ночной+авто", "ночной режим") { s, v -> s.updateChatPrefs { it.copy(nightAuto = v) } },
