        t("Пауза музыки при записи", "пауза+запис", "музык+запис") { s, v -> s.updateChatPrefs { it.copy(pauseMusicOnRecord = v) } },
        t("Пауза музыки при просмотре медиа", "музык+медиа", "музык+видео") { s, v -> s.updateChatPrefs { it.copy(pauseMusicOnMedia = v) } },
