        t("Тактильный отклик", "тактильн", "haptic", "отклик") { s, v -> s.updateChatPrefs { it.copy(haptics = v) } },
        t("Размытие под сообщениями", "размыт+сообщен", "размыт+пузыр", "размыт+блок") { s, v -> s.updateChatPrefs { it.copy(bubbleBlur = v) } },
        t("Синхронизация контактов", "синхрониз") { s, v -> s.updatePrivacyPrefs { it.copy(syncContacts = v) } },
        t("Предпросмотр ссылок", "предпросмотр+ссыл", "превью+ссыл", "ссылок") { s, v -> s.updatePrivacyPrefs { it.copy(linkPreview = v) } },
        t("Скрыть мой номер и юзернейм", "скрыть+номер", "скрой+номер", "мой номер", "свой номер", "юзернейм") { s, v -> s.updatePrivacyPrefs { it.copy(hideOwnContacts = v) } },
        t("Скрывать номер при записи экрана", "запис+экран", "трансляц+экран") { s, v -> s.updatePrivacyPrefs { it.copy(hideOwnContactsOnRecord = v) } },
        t("Автозагрузка по мобильной сети", "автозагрузк+мобильн") { s, v -> s.updateDataPrefs { it.copy(autoMobile = v) } },
