        t("Сохранять в галерею из групп", "галере+групп") { s, v -> s.updateDataPrefs { it.copy(saveToGalleryGroups = v) } },
        t("Сохранять в галерею из каналов", "галере+канал") { s, v -> s.updateDataPrefs { it.copy(saveToGalleryChannels = v) } },
        t("Потоковое воспроизведение", "потоков") { s, v -> s.updateDataPrefs { it.copy(streamMedia = v) } },
        t("Потоковое воспроизведение MKV", "mkv") { s, v -> s.updateDataPrefs { it.copy(streamMkv = v) } },
        t("Режим призрака", "призрак") { s, v -> s.updateGhost { it.copy(enabled = v) } },
        t("Читать чат при отправке (призрак)", "читать+отправк", "прочитать+отправ") { s, v -> s.updateGhost { it.copy(readOnAction = v) } },
        t("Сохранять удалённые сообщения", "удален+сохран", "сохран+удален", "удален+сообщен") { s, v -> s.updateSpy { it.copy(saveDeleted = v) } },
        t("Сохранять правки сообщений", "правк", "редактирован") { s, v -> s.updateSpy { it.copy(saveEdits = v) } },
        t("Сохранять в ботах", "сохран+бот") { s, v -> s.updateSpy { it.copy(saveInBots = v) } },
        t("Сохранять дату прочтения", "дата+прочт", "прочтен") { s, v -> s.updateSpy { it.copy(saveReadDate = v) } },
        t("Сохранять время последнего визита", "последн+онлайн", "был в сети", "последн+визит") { s, v -> s.updateSpy { it.copy(saveLastOnline = v) } },
        t("Сохранять вложения", "вложен") { s, v -> s.updateSpy { it.copy(saveAttachments = v) } },
        t("Сохранять вложения из каналов", "вложен+канал") { s, v -> s.updateSpy { it.copy(attachmentsChannels = v) } },
        t("Фильтры сообщений", "фильтр") { s, v -> s.updateFilters { it.copy(enabled = v) } },
        t("Общие фильтры в чатах", "общие фильтр", "общих фильтр") { s, v -> s.updateFilters { it.copy(sharedInChats = v) } },
        t("Скрывать сообщения заблокированных", "скрыв+заблокир", "скрыть+заблокир", "скрыть+черн") { s, v -> s.updateFilters { it.copy(hideBlocked = v) } },
        t("Слежка за набором текста", "набор+текст", "печатает", "typing") { s, v -> s.updateTypingWatch { it.copy(enabled = v) } },
        t("Слежка за набором в личных чатах", "печата+личн", "набор+личн") { s, v -> s.updateTypingWatch { it.copy(inPrivate = v) } },
        t("Расширенные настройки камеры", "камер+расширен") { s, v -> s.updateCamera { it.copy(advanced = v) } },
        t("Запоминать последнюю камеру", "запомин+камер") { s, v -> s.updateCamera { it.copy(rememberLast = v) } },
        t("Слайдер зума", "зум") { s, v -> s.updateCamera { it.copy(zoomSlider = v) } },
        t("Статичный зум", "статичн") { s, v -> s.updateCamera { it.copy(staticZoom = v) } },
        t("Улучшенный интерфейс", "улучшенн") { s, v -> s.setEnhancedUi(v) },
        t("Курсив в шрифте", "курсив") { s, v -> s.setFontItalic(v) },
        t("Значок Yougram", "значок+yougram", "бейдж", "badge") { s, v -> s.setBadge(v) },
        t("Stream ALL Videos", "stream+all", "стрим+все", "все видео") { s, v -> s.updateDataPrefs { it.copy(streamAll = v) } },
        t("Локальный Premium", "premium", "премиум", "звезд") { s, v -> s.setLocalPremium(v) },
